# Check if there are any differences in how sieve/factor handle special inputs
import sys
sys.path.insert(0, '.')
from more_itertools.recipes import sieve, factor

# Test with float inputs
for val in [5.0, 10.5, -1.0]:
    for func_name, func in [('sieve', sieve), ('factor', factor)]:
        try:
            result = list(func(val))
            print(f"{func_name}({val}) = {result}")
        except Exception as e:
            print(f"{func_name}({val}) raised {type(e).__name__}: {e}")

print()

# Test with None
for val in [None]:
    for func_name, func in [('sieve', sieve), ('factor', factor)]:
        try:
            result = list(func(val))
            print(f"{func_name}({val}) = {result}")
        except Exception as e:
            print(f"{func_name}({val}) raised {type(e).__name__}: {e}")

print()

# Test with very large numbers
for n in [10**6, 10**7, 10**8]:
    try:
        result = list(sieve(n))
        print(f"sieve({n}) has {len(result)} primes")
    except Exception as e:
        print(f"sieve({n}) raised {type(e).__name__}: {e}")
